-- Catalogo precargado de servicios y practicas (568 servicios, 79 practicas).
--
-- Hasta aca el catalogo global de servicios nacia vacio: cada despliegue dependia de que la
-- plataforma cargara a mano lo que los centros pueden ofrecer. Esta migracion lo siembra con dos
-- listas que el usuario armo el 22/11/2026: actividades (pilates, yoga, gimnasia, entrenamiento,
-- talleres...) y prestaciones de kinesiologia y fisioterapia por especialidad.
--
-- Decisiones:
--   * Lo que un centro OFRECE y agenda es un servicio global. El centro no "adopta" nada: lo elige
--     al crear la actividad de su sede, que es la oferta, como con cualquier servicio global.
--   * Las TECNICAS (agentes fisicos, terapia manual, metodos como RPG o Bobath) no son servicios:
--     se aplican dentro de una sesion. Van como practicas globales de Kinesiologia o Fisioterapia,
--     que es donde las toman el tratamiento realizado y los aranceles. Decision del usuario.
--   * servicio.categoria agrupa el selector y no decide ningun comportamiento (RN-M06-005 vale
--     para ella igual que para naturaleza). Es texto libre y nullable: un servicio propio no la
--     tiene, y fijar una lista cerrada seria decidir el vocabulario de cada centro.
--   * Un nombre repetido entre las dos listas queda UNA vez, con la categoria clinica. Naturaleza,
--     modalidad y los dos defaults clinicos son PROPUESTAS: la oferta manda (RF-M06-006).
--   * Idempotente contra lo que ya exista: si la plataforma ya cargo un servicio o una practica
--     global con el mismo codigo o nombre, ON CONFLICT DO NOTHING lo respeta. A un servicio global
--     existente con el mismo nombre y sin categoria solo se le completa la categoria.
--   * Electroterapia, magnetoterapia, ultrasonido y laser ya estaban en V13; no se duplican.

ALTER TABLE servicio ADD COLUMN categoria varchar(80) COLLATE akine_ci;

COMMENT ON COLUMN servicio.categoria IS 'Agrupador del catalogo (ej. "Kinesiologia neurologica"). Solo ordena los selectores: no decide comportamiento. NULL en los servicios propios creados desde cero; la copia que personaliza un global lo hereda';

CREATE TEMPORARY TABLE semilla_servicio
(
    codigo varchar(64) COLLATE akine_ci NOT NULL,
    nombre varchar(160) COLLATE akine_ci NOT NULL,
    categoria varchar(80) COLLATE akine_ci NOT NULL,
    naturaleza varchar(24) NOT NULL,
    modalidad varchar(16) NOT NULL,
    requiere_caso boolean NOT NULL,
    genera_registro boolean NOT NULL
);


UPDATE servicio s
SET categoria = d.categoria, updated_at = CURRENT_TIMESTAMP
FROM semilla_servicio d
WHERE s.organization_id IS NULL
  AND s.categoria IS NULL
  AND s.nombre = d.nombre;

                      requiere_caso_clinico_default, genera_registro_clinico_default, categoria,
                      active, version, created_at, updated_at)
SELECT NULL, d.codigo, d.nombre, NULL, d.naturaleza, d.modalidad, d.requiere_caso, d.genera_registro,
       d.categoria, true, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM semilla_servicio d
ON CONFLICT DO NOTHING;

